// Удобный помощник перевода RU / KZ
function T(ru, kz) {
  return window.BN_STATE.lang === 'kz' ? (kz || ru) : ru;
}

// Правильное склонение числительных на русском языке (исключает «62 литров» и «153 эпизодов»)
function pluralRu(n, one, few, many) {
  const abs = Math.abs(Math.round(n));
  const mod100 = abs % 100;
  const mod10 = abs % 10;
  if (mod100 >= 11 && mod100 <= 19) return many;
  if (mod10 === 1) return one;
  if (mod10 >= 2 && mod10 <= 4) return few;
  return many;
}

function trainerSafetyNote() {
  return `
    <div class="bn-trainer-safety-note">
      ${T(
        'ℹ️ Учебный тренажёр не заменяет очное обучение. При реальной опасности немедленно звоните 112.',
        'ℹ️ Оқу тренажері бетпе-бет оқытуды алмастырмайды. Нақты қауіп төнгенде дереу 112 нөміріне қоңырау шалыңыз.'
      )}
    </div>
  `;
}

